CREATE TYPE "public"."inventory_transaction_type" AS ENUM('receipt','issue','adjustment');
CREATE TYPE "public"."procurement_status" AS ENUM('draft','submitted','approved','ordered','received','cancelled');
CREATE TYPE "public"."document_record_status" AS ENUM('draft','issued','revoked');
CREATE TABLE "inventory_items" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "school_id" uuid NOT NULL REFERENCES "schools"("id") ON DELETE CASCADE, "sku" varchar(80) NOT NULL, "name" varchar(200) NOT NULL, "category" varchar(100), "unit" varchar(30) DEFAULT 'unit' NOT NULL, "reorder_level" integer DEFAULT 0 NOT NULL, "quantity_on_hand" integer DEFAULT 0 NOT NULL, "is_active" boolean DEFAULT true NOT NULL, "created_at" timestamptz DEFAULT now() NOT NULL, "updated_at" timestamptz DEFAULT now() NOT NULL, CONSTRAINT "inventory_items_school_sku_unique" UNIQUE("school_id","sku"));
CREATE TABLE "inventory_transactions" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "school_id" uuid NOT NULL REFERENCES "schools"("id") ON DELETE CASCADE, "item_id" uuid NOT NULL REFERENCES "inventory_items"("id") ON DELETE RESTRICT, "type" "inventory_transaction_type" NOT NULL, "quantity" integer NOT NULL, "reference" varchar(150), "notes" text, "actor_id" text NOT NULL, "created_at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE "procurement_requests" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "school_id" uuid NOT NULL REFERENCES "schools"("id") ON DELETE CASCADE, "requested_by" text NOT NULL, "supplier" varchar(200), "status" "procurement_status" DEFAULT 'draft' NOT NULL, "notes" text, "total_amount" numeric(12,2) DEFAULT '0' NOT NULL, "created_at" timestamptz DEFAULT now() NOT NULL, "updated_at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE "procurement_request_items" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "request_id" uuid NOT NULL REFERENCES "procurement_requests"("id") ON DELETE CASCADE, "item_id" uuid REFERENCES "inventory_items"("id") ON DELETE RESTRICT, "description" varchar(200) NOT NULL, "quantity" integer NOT NULL, "unit_price" numeric(12,2) NOT NULL);
CREATE TABLE "document_records" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "school_id" uuid NOT NULL REFERENCES "schools"("id") ON DELETE CASCADE, "student_id" uuid REFERENCES "students"("id") ON DELETE CASCADE, "document_type" varchar(80) NOT NULL, "document_number" varchar(100) NOT NULL, "title" varchar(200) NOT NULL, "payload" jsonb DEFAULT '{}' NOT NULL, "status" "document_record_status" DEFAULT 'draft' NOT NULL, "issued_at" timestamptz, "issued_by" text NOT NULL, "created_at" timestamptz DEFAULT now() NOT NULL, CONSTRAINT "document_records_school_number_unique" UNIQUE("school_id","document_number"));
CREATE INDEX "inventory_items_school_idx" ON "inventory_items" ("school_id");
CREATE INDEX "inventory_transactions_school_idx" ON "inventory_transactions" ("school_id");
CREATE INDEX "inventory_transactions_item_idx" ON "inventory_transactions" ("item_id");
CREATE INDEX "procurement_requests_school_idx" ON "procurement_requests" ("school_id");
CREATE INDEX "procurement_requests_status_idx" ON "procurement_requests" ("status");
CREATE INDEX "procurement_request_items_request_idx" ON "procurement_request_items" ("request_id");
CREATE INDEX "document_records_school_idx" ON "document_records" ("school_id");
CREATE INDEX "document_records_student_idx" ON "document_records" ("student_id");
